import{_ as l,l as i,o as t,c as p,v as e,p as n,x as o,d as r,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"caps / floors / swaptions","description":"","frontmatter":{"title":"caps / floors / swaptions","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/caps-floors-swaptions.md","filePath":"quant/caps-floors-swaptions.md","lastUpdated":1789023840000}'),h={name:"quant/caps-floors-swaptions.md"};function B(m,a,f,u,_,w){const s=i("Mermaid");return t(),p("div",null,[a[1]||(a[1]=e('<h1 id="caps-floors-swaptions" tabindex="-1">caps / floors / swaptions <a class="header-anchor" href="#caps-floors-swaptions" aria-label="Permalink to &quot;caps / floors / swaptions&quot;">​</a></h1><div class="epigraph"><p>Cap 是一串 caplet；swaption 是对整条互换的期权。二者的隐波不能用同一个对数正态 $F$ 去混用，除非经过一致性模型。</p><footer>—— Black, The Pricing of Commodity Contracts 的 caplet 用法；Jamshidian 对欧式 swaption 在 Vasicek 下的分解；市场报价见 ISDA 定义</footer></div><p><a href="/quant/inflation-linked">上一课</a>把实际利率曲线立起来。本课回到名义利率期权：cap/floor 与欧式 swaption。主干 <a href="/quant/lmm">LMM</a>、<a href="/quant/hull-white">Hull–White</a> 已写模型。缺口是<strong>产品与报价</strong>：caplet 的 Black 公式、swaption 的互换测度、以及两者如何共同约束后课 SABR-LMM。负利率放到下一课移位。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Cap 支付 \\(\\sum \\delta_i(L_i-K)^+\\)，每段 caplet 在其自身远期测度下是 Black-76。Floor 对称。Swaption 支付年金乘 \\((S-K)^+\\)，在年金测度下也是 Black。问题是同一 \\(K\\) 的 cap 隐波与对应到期的 swaption 隐波一般不一致：一个吃的是单点远期，一个吃的是互换率（远期的加权）。没有期限结构模型，不能把 cap 曲面「转换成」swaption 曲面去对冲。</p><p>物理交割 vs 现金交割（cash-settled swaption 的年金公式）改变测度，欧洲现金交割惯例会让 Black 公式的 \\(A\\) 与实物交割不同。实现必须按确认书选。</p><h3 id="互换率不是某个-caplet-的" tabindex="-1">互换率不是某个 caplet 的 \\(L\\) <a class="header-anchor" href="#互换率不是某个-caplet-的" aria-label="Permalink to &quot;互换率不是某个 caplet 的 $L$&quot;">​</a></h3><p>Jamshidian 在单因子 Hull–White 下把欧式 swaption 写成债券期权的和，从而有闭式。多因子或 LMM 下没有这层分解，要用换测度后的近似（Rebonato 冻结权重）或模拟。把 swaption 当「平均到期的 caplet」，对冲会漏掉曲线形态风险。</p><p><span class="marginnote">Cap 的 ATM 常定义在即期互换率或每段远期自己的 ATM，惯例因币种而异。又是报价课的坐标问题。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Caplet 剥离：从最短 cap 开始剥离 caplet 隐波，注意重叠与日计数。Swaption 网格：到期 × 期限。校准 HW：用部分 swaption；校准 LMM：用 swaption 网格为主，cap 为辅或反过来，视簿的产品。对冲：cap 用期货/FRA 与 caplet 桶；swaption 用对应互换 + 曲线桶 + vol 桶。AAD 穿过年金与互换率定义。</p><p>微笑：每个 caplet、每个 swaption 格子一个 SABR，下一课再谈如何让 LMM 同时吃下这些微笑。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Caplet 是对单点 Libor/RFR 复合率的期权；swaption 是对曲线上一条加权平均的期权。相关：曲线因子若高度相关，二者接近；若曲率因子大，长期限 swaption 与一串 caplet 的差就是曲线形态的期权。这正是为什么需要 <a href="/quant/hjm">HJM</a>/LMM 而不是一个股式 GBM。</p>',14)),(t(),n(d,null,{default:o(()=>[c(s,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20Cap%5B%22Cap%20%E4%B8%80%E4%B8%B2%20caplet%22%5D%20--%3E%20BlkC%5B%22%E5%90%84%E8%BF%9C%E6%9C%9F%E6%B5%8B%E5%BA%A6%20Black%22%5D%0A%20%20Swp%5B%22Swaption%22%5D%20--%3E%20Ann%5B%22%E5%B9%B4%E9%87%91%E6%B5%8B%E5%BA%A6%20Black%22%5D%0A%20%20BlkC%20--%3E%20Inc%5B%22%E4%BA%8C%E8%80%85%E9%9A%90%E6%B3%A2%E4%B8%8D%E4%B8%80%E8%87%B4%22%5D%0A%20%20Ann%20--%3E%20Inc%0A%20%20Inc%20--%3E%20Mod%5B%22HW%20%E6%88%96%20LMM%20%E5%81%9A%E4%B8%80%E8%87%B4%E6%80%A7%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>RFR 过渡后 cap 写在每日复利的 RFR 上，剥离与日内复合改变有效波动，不能沿用 Libor caplet 代码。负利率使 lognormal Black 爆炸，必须移位或用 Bachelier，见下一课。微笑翼部流动性差，剥离不稳定，要正则化。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Cap 是 caplet 之和，swaption 是互换率期权；隐波不可直接混用。</li><li>现金与实物交割测度不同；Jamshidian 分解限于单因子。</li><li>一致性留给 HW/LMM；本课钉产品与报价。</li><li>出处：Black, <em>JFE</em>, 1976（公式在 caplet 上的应用）；Jamshidian, <em>Finance and Stochastics</em> 等对债券期权分解的工作。</li></ul>',4))])}const k=l(h,[["render",B]]);export{E as __pageData,k as default};
